-- ============================================================================
-- check_prec_instance_clusters.sql
-- Tier 2-5: prec 심급(1심/2심/3심) 중복 판단 문제 - 먼저 규모부터 확인합니다.
-- case_no가 달라도(예: 2016고합50 vs 2016노223 vs 2016도18035) 같은 분쟁을
-- 다루는 클러스터가 얼마나 있는지, "죄명 리스트가 완전히 동일한 서로 다른
-- case_no" 개수로 근사합니다. (완벽한 탐지는 원심 참조 필드가 없어 불가능하지만,
-- 규모 가늠에는 충분합니다)
-- ============================================================================

-- [1] head_1(요약) 기준, 죄명 부분(title에서 사건번호와 (요약-N) 제외)이
--     완전히 동일한데 case_no가 다른 그룹 개수/청크 수
--     title 형식: "법령해석례..." 대신 prec는 "판례 [사건번호] 죄명 (요약-N)"
--     -> 사건번호와 (요약-N) 부분을 제거하고 죄명만 남겨 그룹핑합니다.
WITH normalized AS (
    SELECT
        chunk_id,
        doc_id,
        title,
        regexp_replace(title, '^판례 \[[^\]]+\] (.+?) \(요약.*\)$', '\1') AS charge_names
    FROM legal_chunks
    WHERE doc_type = 'prec'
      AND chunk_id LIKE '%\_head\_1'
)
SELECT charge_names, COUNT(DISTINCT doc_id) AS distinct_case_count,
       array_agg(DISTINCT doc_id ORDER BY doc_id) AS doc_ids
FROM normalized
GROUP BY charge_names
HAVING COUNT(DISTINCT doc_id) > 1
ORDER BY distinct_case_count DESC
LIMIT 30;

