-- [2] 위 결과의 전체 규모 (몇 개 클러스터, 몇 개 doc_id가 영향받는지)
WITH normalized AS (
    SELECT
        doc_id,
        regexp_replace(title, '^판례 \[[^\]]+\] (.+?) \(요약.*\)$', '\1') AS charge_names
    FROM legal_chunks
    WHERE doc_type = 'prec'
      AND chunk_id LIKE '%\_head\_1'
),
clusters AS (
    SELECT charge_names, COUNT(DISTINCT doc_id) AS cnt
    FROM normalized
    GROUP BY charge_names
    HAVING COUNT(DISTINCT doc_id) > 1
)
SELECT COUNT(*) AS cluster_count,
       SUM(cnt) AS affected_doc_ids
FROM clusters;

